<template><article class="card visitor-pass-card"><div><h3>{{pass.plate_no}} <VisitorPassStatusBadge :status="pass.status"/></h3><p>{{pass.building}} {{pass.unit}} {{pass.room}} · 申请人 {{pass.user?.nickname||'业主'}}</p><p>有效时段：{{fmt(pass.visit_start)}} ~ {{fmt(pass.visit_end)}}</p><p v-if="pass.fail_reason" class="fail-reason">审批失败：{{pass.fail_reason}}</p><small>提交于 {{fmt(pass.created_at)}}</small></div><div class="visitor-pass-actions"><el-button v-if="canApprove" size="small" type="primary" @click="$emit('approve',pass.id)">批准</el-button><el-button v-if="canRevoke" size="small" type="danger" plain @click="$emit('revoke',pass.id)">撤销</el-button></div></article></template><script setup lang="ts">import type{VisitorPass}from'../../types';import VisitorPassStatusBadge from'./VisitorPassStatusBadge.vue';defineProps<{pass:VisitorPass;canApprove:boolean;canRevoke:boolean}>();defineEmits<{approve:[id:number];revoke:[id:number]}>();const fmt=(v:string)=>new Date(v).toLocaleString()</script>
